public class JSumArrayElements {
	public static void main(String[] args) {
		//Step 1: Define the data and variable that we need for this program
		int[] lst = {12, 15, 3, 4, 6, 5};
		int total = 0;
	    //Step 2: Iterate through the array values and add each value to the running total
		for (int x : lst) {
		    total += x;
		}
	    //Step 3: Print the sum of the array values 
		System.out.println("The sum of values in the array: " + total);
	}
}
